    // Herbst: gelbe T\xF6ne und Laub
    wiese = mix(wiese, wiese*vec3(1.25,1.0,0.6), u_herbst*0.4*smoothstep(0.4,0.8,gross));

    // ---------- Rasen: gem\xE4ht, Streifen ----------
